for filename in ['achievement-story.png','achievement-story-v2.png']:
    p=root/'img'/filename
    if p.exists():
        e=dict(entries['image6'])
        e.update(file=filename,title='Achievement spaceship draft',similar_to=['image6'],review_notes=['Earlier variant of image6; do not count as a new concept.'])
        if filename=='achievement-story.png':
            e['solutions']='The father plays in a cardboard spaceship with his child; this draft omits Goodie from the final panel.'
        entries[p.stem]=e

files=sorted((root/'img').glob('*.png'))
for key,values in json.loads((root/'story-index-additions.json').read_text(encoding='utf-8')).items():
    title,problem,actions,solution,message,need,principle,similar=values
    if (root/'img'/(key+'.png')).exists():
        entries[key]={'file':key+'.png','title':title,'problem':problem,'goodie_actions':actions,'solutions':solution,'message':message,'underlying_need':need,'principle':principle,'similar_to':['image'+str(n) for n in similar],'review_basis':'Visual inspection of the actual image','review_notes':[]}
entries['image49']['similar_to']=['image18','image34','image36','image39']
hashes={}
for p in files:
    digest=hashlib.sha256(p.read_bytes()).hexdigest()
    hashes.setdefault(digest,[]).append(p.stem)
duplicates=[v for v in hashes.values() if len(v)>1]
for group in duplicates:
    for key in group:
        if key in entries: entries[key]['exact_duplicate_of']=[x for x in group if x!=key]

data={'domain':'givegoodnews.com','review_date':'2026-11-17','purpose':'Review these problems, Goodie actions, solutions and similar concepts before creating another image. Changing a character, prop or wording does not make the underlying story new.','image_count':len(entries),'numbered_story_count':sum(k.startswith('image') for k in entries),'exact_duplicate_groups':duplicates,'images':entries}
(root/'image-story-index.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'indexed':len(entries),'exact_duplicates':duplicates}))
